test('invoiceTotals sums VAT across lines with different rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, vatRate: 21 },
      { qty: 1, unitPrice: 1000, vatRate: 9 },
      { qty: 1, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 1000 * 21 / 100 = 210
  // Line 2: 1000 * 9 / 100 = 90
  // Line 3: 1000 * 0 / 100 = 0
  // Total VAT: 300
  assert.equal(totals.subtotal, 3000);
  assert.equal(totals.vat, 300);
  assert.equal(totals.total, 3300);
});

test('invoiceTotals with mixed discounts and VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 1000, discountPercent: 20, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal 1000, discount 100, after discount 900, vat 189
  // Line 2: subtotal 1000, discount 200, after discount 800, vat 72
  // Total: subtotal 2000, discount 300, vat 261, total 1961
  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 300);
  assert.equal(totals.vat, 261);
  assert.equal(totals.total, 1961);
});

test('invoiceTotals clamps total to 0 even with VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000, Discount: 1000, After discount: 0, VAT: 0
  // Total: 1000 - 1000 + 0 = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

