  const line = { qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Amount: 1000, Discount: 100, After discount: 900
  // VAT: 900 * 21 / 100 = 189
  assert.equal(lineVat(line), 189);
});

test('lineVat defaults vatRate to 0', () => {
